import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be positive")
    system = platform.system()
    if system == "Windows":
        command = ['wmic', 'cpu', 'get', 'loadpercentage']
    else:
        command = ['top', '-bn1']
    data = []
    end_time = time.time() + duration
    while time.time() < end_time:
        timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
        try:
            output = subprocess.check_output(command, stderr=subprocess.DEVNULL).decode()
            if system == "Windows":
                usage = float(output.strip().split()[-1])
            else:
                usage_line = [line for line in output.split('\n') if '%Cpu(s)' in line][0]
                usage = float(usage_line.split()[1].replace(',', '.'))
        except Exception:
            usage = 0.0
        data.append({'timestamp': timestamp, 'cpu_usage': usage})
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(data, f)
    except IOError:
        return None
    return LOGFILE_PATH

