import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero")
    records = []
    start_time = time.time()
    system_platform = platform.system()
    while time.time() - start_time < duration:
        timestamp = time.time()
        if system_platform == "Windows":
            output = subprocess.check_output(['wmic', 'cpu', 'get', 'loadpercentage'], text=True)
            cpu_usage = float(output.strip().split('\n')[1].strip())
        else:
            output = subprocess.check_output(['top', '-bn1'], text=True)
