                    break
        records.append({'timestamp': timestamp, 'cpu_usage': cpu_usage})
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, 'w') as log_file:
            json.dump(records, log_file)
        return LOGFILE_PATH
    except IOError:
        return None

