import time
def task_func(test_dir):
    result = {}
    python_files = glob.glob(os.path.join(test_dir, '**', '*.py'), recursive=True)
    for file in python_files:
        start_time = time.time()
        try:
            subprocess.run(['python', file], check=True, capture_output=True)
        except subprocess.CalledProcessError:
            pass
        end_time = time.time()
        result[os.path.basename(file)] = end_time - start_time
