            existing_data = json.load(f)
        if isinstance(existing_data, list):
            existing_data.append(log_data)
        else:
            existing_data = [existing_data, log_data]
        with open(log_file, 'w') as f:
            json.dump(existing_data, f)
    else:
        with open(log_file, 'w') as f:
            json.dump([log_data], f)
    return log_data

